SELECT "symbol", "issue", "status", "name", "exchangeid", "sk_companyid", "sharesoutstanding", "firsttrade", "firsttradeonexchange", "dividend", "iscurrent", "batchid", "effectivedate", "enddate", CAST(ROW_NUMBER() OVER (ORDER BY symbol, effectivedate) AS int) AS "sk_securityid" FROM (SELECT TRY_CAST((sec.Symbol) AS char(15)) AS "symbol", TRY_CAST((CAST(sec.IssueType AS CHAR(6))) AS char(6)) AS "issue", TRY_CAST((CAST(sec.Status AS CHAR(10))) AS char(10)) AS "status", TRY_CAST((CAST(sec.Name AS CHAR(70))) AS char(70)) AS "name", TRY_CAST((CAST(sec.ExID AS CHAR(6))) AS char(6)) AS "exchangeid", TRY_CAST((CAST(hash(sec.CoNameOrCIK) % 2147483648 AS INT)) AS int) AS "sk_companyid", TRY_CAST((CAST(sec.ShOut AS INTEGER)) AS int) AS "sharesoutstanding", TRY_CAST((try_cast(substr(sec.FirstTradeDate, 1, 4) || '-' || substr(sec.FirstTradeDate, 5, 2) || '-' || substr(sec.FirstTradeDate, 7, 2) AS DATE)) AS date) AS "firsttrade", TRY_CAST((CAST(strptime(sec.FirstTradeExchg, '%Y%m%d') AS DATE)) AS date) AS "firsttradeonexchange", TRY_CAST((CAST(CAST(sec.Dividend AS DOUBLE) AS INTEGER)) AS int) AS "dividend", CAST(NULL AS boolean) AS "iscurrent", TRY_CAST((CAST(NULL AS DECIMAL(5))) AS decimal(5)) AS "batchid", TRY_CAST((make_date(CAST(SUBSTRING(sec.PTS, 1, 4) AS INTEGER), CAST(SUBSTRING(sec.PTS, 5, 2) AS INTEGER), CAST(SUBSTRING(sec.PTS, 7, 2) AS INTEGER))) AS date) AS "effectivedate", TRY_CAST((CAST('9999-12-31' AS DATE)) AS date) AS "enddate" FROM FinwireSEC sec LEFT JOIN StatusType st ON sec.Status = st.ST_ID)
